/**
 * Renaming a workspace's URL slug (ADR 0005): choice, availability, the hold
 * on the retired slug, chains, permission and announcements.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { TenantScopeError } from "@/lib/tenant";
import { activityFilterSchema, activityActionSchema } from "@/schemas/activity";
import { renameOrganizationSlugSchema } from "@/schemas/organization";
import * as orgRepo from "@/server/repositories/organization-repository";
import { listActivity } from "@/server/services/activity-service";
import {
  createOrganization,
  getOrganizationSummary,
  listOrganizationsForUser,
  renameOrganizationSlug,
  resolveOrgBySlug,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const START = Date.UTC(2026, 5, 1, 12, 0, 0, 0);

let cleanup: () => void;
let seq = 0;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

/** A fresh tenant whose slug cannot collide with any other test's. */
async function tenantNamed(prefix: string): Promise<Tenant> {
  seq += 1;
  return createTenant(`${prefix}-${seq}`);
}

function rename(tenant: Tenant, slug: string, role: keyof Tenant["actors"] = "admin") {
  return renameOrganizationSlug(tenant.actors[role], { orgId: tenant.org.id, slug });
}

async function actorFor(tenant: Tenant, slug: string) {
  const principal = {
    userId: tenant.userIds.owner,
    email: "owner@example.test",
    activeOrgId: tenant.org.id,
    expiresAt: new Date(START + 365 * MS_PER_DAY).toISOString(),
  } as unknown as SessionPrincipal;
  return resolveActorForOrg(principal, slug);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

describe("renameOrganizationSlug", () => {
  it("changes the slug everywhere it is read and leaves the rest alone", async () => {
    const tenant = await tenantNamed("alpha");
    const before = tenant.org;

    const renamed = await rename(tenant, "alpha-renamed");

    expect(renamed.slug).toBe("alpha-renamed");
    expect(renamed).toMatchObject({
      id: before.id,
      name: before.name,
      plan: before.plan,
      ownerId: before.ownerId,
      settings: before.settings,
      archivedAt: null,
    });

    expect(await orgRepo.findOrgById(before.id)).toEqual(renamed);
    const summary = await getOrganizationSummary(tenant.actors.member, before.id);
    expect(summary.organization.slug).toBe("alpha-renamed");
    const listed = await listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === before.id)?.slug).toBe("alpha-renamed");
    expect((await resolveOrgBySlug("alpha-renamed"))?.id).toBe(before.id);
    expect((await actorFor(tenant, "alpha-renamed"))?.orgId).toBe(before.id);
  });

  it("keeps the old slug resolving through every lookup until the hold ends", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const tenant = await tenantNamed("hold");
    const oldSlug = tenant.org.slug;

    await rename(tenant, `${oldSlug}-new`);

    for (const offset of [0, 1, ORG_SLUG_HOLD_DAYS * MS_PER_DAY - 1]) {
      vi.setSystemTime(START + offset);
      expect((await resolveOrgBySlug(oldSlug))?.id).toBe(tenant.org.id);
      expect((await orgRepo.findOrgBySlug(oldSlug))?.id).toBe(tenant.org.id);
      expect((await actorFor(tenant, oldSlug))?.orgId).toBe(tenant.org.id);
      expect((await resolveOrgBySlug(oldSlug))?.slug).toBe(`${oldSlug}-new`);
    }

    vi.setSystemTime(START + ORG_SLUG_HOLD_DAYS * MS_PER_DAY);
    expect(await resolveOrgBySlug(oldSlug)).toBeNull();
    expect(await orgRepo.findOrgBySlug(oldSlug)).toBeNull();
    expect(await actorFor(tenant, oldSlug)).toBeNull();
  });

  it("refuses a slug another workspace holds as current or retired, never suffixing", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
