  });

  it("keeps the old slug resolving through every lookup until the hold ends", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const tenant = await tenantNamed("hold");
    const oldSlug = tenant.org.slug;

    await rename(tenant, `${oldSlug}-new`);

    for (const offset of [0, 1, ORG_SLUG_HOLD_DAYS * MS_PER_DAY - 1]) {
      vi.setSystemTime(START + offset);
      expect((await resolveOrgBySlug(oldSlug))?.id).toBe(tenant.org.id);
      expect((await orgRepo.findOrgBySlug(oldSlug))?.id).toBe(tenant.org.id);
      expect((await actorFor(tenant, oldSlug))?.orgId).toBe(tenant.org.id);
      expect((await resolveOrgBySlug(oldSlug))?.slug).toBe(`${oldSlug}-new`);
    }

    vi.setSystemTime(START + ORG_SLUG_HOLD_DAYS * MS_PER_DAY);
    expect(await resolveOrgBySlug(oldSlug)).toBeNull();
    expect(await orgRepo.findOrgBySlug(oldSlug)).toBeNull();
    expect(await actorFor(tenant, oldSlug)).toBeNull();
  });

  it("refuses a slug another workspace holds as current or retired, never suffixing", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const a = await tenantNamed("refuse-a");
    const b = await tenantNamed("refuse-b");
    const retired = a.org.slug;
    await rename(a, `${retired}-x`);

    await expect(rename(b, a.org.slug.replace(/-x$/, "") + "-x")).rejects.toBeInstanceOf(
      InvalidSlugError,
    );
    await expect(rename(b, retired)).rejects.toBeInstanceOf(InvalidSlugError);
    expect((await orgRepo.findOrgById(b.org.id))?.slug).toBe(b.org.slug);

    vi.setSystemTime(START + ORG_SLUG_HOLD_DAYS * MS_PER_DAY);
    const taken = await rename(b, retired);
    expect(taken.slug).toBe(retired);
    expect((await resolveOrgBySlug(retired))?.id).toBe(b.org.id);
  });

  it("refuses a deleted workspace's slug and bad shapes", async () => {
    const a = await tenantNamed("gone");
    const b = await tenantNamed("living");
    await orgRepo.archiveOrg(a.org.id);

    await expect(rename(b, a.org.slug)).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(rename(b, "admin")).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(rename(b, "Not Valid")).rejects.toBeInstanceOf(InvalidSlugError);
  });

  it("derives a suffix at creation when the slug is held, and not once it is released", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const tenant = await tenantNamed("creation");
    const oldSlug = tenant.org.slug;
    await rename(tenant, `${oldSlug}-moved`);

    const held = await createOrganization(tenant.userIds.owner, {
      name: "Held",
      slug: oldSlug,
      plan: "free",
    });
    expect(held.slug).toBe(`${oldSlug}-2`);

    vi.setSystemTime(START + ORG_SLUG_HOLD_DAYS * MS_PER_DAY);
    const released = await createOrganization(tenant.userIds.owner, {
      name: "Released",
      slug: oldSlug,
      plan: "free",
    });
    expect(released.slug).toBe(oldSlug);
    expect((await resolveOrgBySlug(oldSlug))?.id).toBe(released.id);
  });

  it("keeps every earlier slug on its own hold across a chain", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const tenant = await tenantNamed("chain");
    const first = tenant.org.slug;

    await rename(tenant, `${first}-b`);
    vi.setSystemTime(START + 10 * MS_PER_DAY);
    await rename(tenant, `${first}-c`);

    vi.setSystemTime(START + 29 * MS_PER_DAY);
    expect((await resolveOrgBySlug(first))?.slug).toBe(`${first}-c`);
    expect((await resolveOrgBySlug(`${first}-b`))?.slug).toBe(`${first}-c`);

    vi.setSystemTime(START + 30 * MS_PER_DAY);
    expect(await resolveOrgBySlug(first)).toBeNull();
    expect((await resolveOrgBySlug(`${first}-b`))?.slug).toBe(`${first}-c`);

    vi.setSystemTime(START + 40 * MS_PER_DAY);
    expect(await resolveOrgBySlug(`${first}-b`)).toBeNull();
  });

  it("renaming back ends the retirement and retires the slug being replaced", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const tenant = await tenantNamed("back");
    const first = tenant.org.slug;
    const other = await tenantNamed("rival");

    await rename(tenant, `${first}-b`);
    vi.setSystemTime(START + MS_PER_DAY);
    const back = await rename(tenant, first);

    expect(back.slug).toBe(first);
    expect((await resolveOrgBySlug(`${first}-b`))?.id).toBe(tenant.org.id);
    await expect(rename(other, `${first}-b`)).rejects.toBeInstanceOf(InvalidSlugError);

    // The retirement of `first` is gone: nothing but the live slug keeps it.
    vi.setSystemTime(START + 60 * MS_PER_DAY);
    expect((await resolveOrgBySlug(first))?.id).toBe(tenant.org.id);
    expect(await resolveOrgBySlug(`${first}-b`)).toBeNull();
  });

  it("is a no-op for the current slug", async () => {
    const tenant = await tenantNamed("noop");
    const events = capture("organization.slug_changed");

    const same = await rename(tenant, tenant.org.slug);

    expect(same).toEqual(tenant.org);
    expect(events).toHaveLength(0);
    const page = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(0);
  });

  it("needs the permission that updating settings needs, and a refusal changes nothing", async () => {
    const tenant = await tenantNamed("perm");
    const other = await tenantNamed("perm-other");
    const events = capture("organization.slug_changed");

    await expect(rename(tenant, `${tenant.org.slug}-m`, "member")).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(rename(tenant, `${tenant.org.slug}-v`, "viewer")).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: tenant.org.id,
        slug: `${tenant.org.slug}-o`,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe(tenant.org.slug);
    expect(await resolveOrgBySlug(`${tenant.org.slug}-m`)).toBeNull();
    expect(events).toHaveLength(0);
  });

  it("publishes organization.slug_changed once and audits it once", async () => {
    const tenant = await tenantNamed("announce");
    const events = capture("organization.slug_changed");
    const to = `${tenant.org.slug}-next`;

    await rename(tenant, to);

    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: tenant.org.slug,
      to,
    });

    const page = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: tenant.org.slug, to },
    });
  });

  it("does not publish or audit a refused rename", async () => {
    const tenant = await tenantNamed("refused");
    const other = await tenantNamed("refused-other");
    const events = capture("organization.slug_changed");

    await expect(rename(tenant, other.org.slug)).rejects.toBeInstanceOf(InvalidSlugError);

    expect(events).toHaveLength(0);
    const page = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(0);
  });
});

describe("schemas", () => {
  it("validates rename input with the shared slug rules", () => {
    const orgId = "01HZZZAAAAAAAAAAAAAAAAAAAA";
    expect(renameOrganizationSlugSchema.safeParse({ orgId, slug: "fresh-name" }).success).toBe(true);
    expect(renameOrganizationSlugSchema.safeParse({ orgId, slug: "admin" }).success).toBe(false);
    expect(renameOrganizationSlugSchema.safeParse({ orgId, slug: "Bad Slug" }).success).toBe(false);
  });

  it("accepts the new audit action in activity filters", () => {
    expect(activityActionSchema.safeParse("organization.slug_changed").success).toBe(true);
    const parsed = activityFilterSchema.safeParse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(parsed.success).toBe(true);
  });
});
